def solve(data):
    cursor, calls, items, seen = data['start'], [], [], set()
    limit = data.get('max_items')
    if limit == 0:
        return {'items': [], 'calls': []}
    while True:
        calls.append(cursor)
        page = data['pages'][cursor]
        for item in page['items']:
            if item['id'] not in seen:
                items.append(item)
                seen.add(item['id'])
        if limit is not None and len(items) >= limit:
            items = items[:limit]
            break
        if not page['has_more']:
            break
        cursor = page['next']
    return {'items': items, 'calls': calls}

