def solve(data):
    waits, calls, status = [], 0, None
    for response in data['responses']:
        calls += 1
        status = response['status']
        if status == 200 or status not in data['retryable'] or not data.get('method_safe', True):
            break
        if calls >= data['max_attempts'] or calls >= len(data['responses']):
            break
        delay = response['delay']
        if 'budget' in data and sum(waits) + delay > data['budget']:
            return {'calls': calls, 'status': status, 'waits': waits, 'stop': 'budget'}
        waits.append(delay)
    return {'calls': calls, 'status': status, 'waits': waits}

